window.MOTIF_CATALOG_CHUNKS[106]={"cards":[{"id":"MEJE-KW-010733","row_version":2,"title":"새내기 시절의 두려움","original":"Freshman Fears","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"새 학교에 들어간 인물이 낯선 생활과 공부, 또래 관계를 걱정하며 첫해를 힘들게 보낸다. 낯선 학교에서 친구를 아직 사귀지 못한 상태는 친구가 없음을 보여 주는 배경으로 말없이 보일 수 있다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-010733/index.html"},{"id":"MEJE-KW-010734","row_version":1,"title":"정신분석실의 긴 의자","original":"Freudian Couch","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"상담받는 인물이 긴 의자에 누워 천장을 보며 이야기하는 모습으로 정신분석 치료 장면임을 빠르게 알린다. 실제 치료 전반을 대표하지는 않는다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-010734/index.html"},{"id":"MEJE-KW-010735","row_version":3,"title":"상처가 악행의 이유가 되다","original":"Freudian Excuse","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"작품이 악역의 가혹한 과거를 드러내 현재 행동이 만들어진 배경을 설명한다. 과거의 상처와 행동의 정당화는 별개로 살필 수 있다. 악역이 자신의 과거와 현재 행동 사이의 연결을 인정하지 않으면 상처의 영향을 부인하다과 이어진다. 과거의 상처가 행동의 이유를 밝혀도 책임을 지우지 않는 판단은 불행한 과거도 악행의 면죄부는 아니다이다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-010735/index.html"},{"id":"MEJE-KW-010736","row_version":1,"title":"상처의 영향을 부인하다","original":"Freudian Excuse Denial","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"주변 인물은 과거의 상처가 현재 행동을 설명한다고 추정하지만 당사자가 그 해석을 거부한다. 실제로 그런 과거가 없거나 있어도 행동의 이유가 아닐 수 있다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-010736/index.html"},{"id":"MEJE-KW-010737","row_version":1,"title":"불행한 과거도 악행의 면죄부는 아니다","original":"Freudian Excuse Is No Excuse","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"작품 속 인물이 가해자의 상처를 이해하면서도 피해를 준 행위에 대한 책임을 분명히 묻는다. 이 판단은 이야기 안에서 실제로 표현된다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-010737/index.html"},{"id":"MEJE-KW-010738","row_version":2,"title":"말실수에 새어 나온 속마음","original":"Freudian Slip","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 하려던 말 대신 감추고 있던 생각을 떠올리게 하는 단어를 잘못 내뱉어 민망함이나 웃음을 만든다. 한 번의 말실수를 수습하려다 비슷한 실수가 연달아 나오면 말실수가 말실수를 부르다으로 커진다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-010738/index.html"},{"id":"MEJE-KW-010739","row_version":1,"title":"말실수가 말실수를 부르다","original":"Freudian Slippery Slope","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"처음 나온 부적절한 말 한마디를 바로잡으려 할수록 새로운 말실수가 이어져 상황이 더 난처해진다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-010739/index.html"},{"id":"MEJE-KW-010740","row_version":2,"title":"성적 불안을 겨냥한 위협","original":"Freudian Threat","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 상대의 신체와 성적 불안을 건드리는 위협적인 말을 던져 불쾌감과 공포를 조성한다. 실제 가해 방법이 아니라 발화의 서사적 기능을 다룬다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-010740/index.html"},{"id":"MEJE-KW-010741","row_version":1,"title":"충동·조정·규범의 세 인물","original":"Freudian Trio","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"세 인물이 각각 본능적인 행동, 현실적인 조율, 규칙과 원칙을 중시하는 태도를 맡아 서로를 견제하며 한 팀을 이룬다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-010741/index.html"},{"id":"MEJE-KW-010742","row_version":2,"title":"모든 것을 성적 상징으로 읽기","original":"Freud Was Right","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품 속 인물이나 서술이 평범한 모양과 말에서까지 숨은 성적 의미를 찾아내는 해석 관습이다. 특정 심리학 이론의 사실 여부를 단정하는 설명은 아니다. 감춰 둔 욕망이 단어 선택에서 새어 나왔다고 읽는 경우는 말실수에 새어 나온 속마음과 맞닿는다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-010742/index.html"},{"id":"MEJE-KW-010743","row_version":1,"title":"마찰로 몸에 불이 붙는 과장","original":"Friction Burn","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 빠른 움직임이나 거친 마찰 뒤 인물에게 불이 붙는다고 과장해 희극이나 초능력의 효과를 만든다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-010743/index.html"},{"id":"MEJE-KW-010744","row_version":1,"title":"멈추지 않고 미끄러지는 얼음 바닥","original":"Frictionless Ice","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임의 얼음 바닥에 올라선 인물이나 물체가 장애물에 닿을 때까지 방향을 바꾸거나 멈출 수 없게 만든다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-010744/index.html"},{"id":"MEJE-KW-010745","row_version":2,"title":"대기권 재진입의 열을 무시하다","original":"Frictionless Reentry","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"우주선이나 인물이 대기권을 빠르게 통과해도 재진입의 열과 위험을 거의 겪지 않는 과학소설의 편의적 연출이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-010745/index.html"},{"id":"MEJE-KW-010746","row_version":1,"title":"금요일 밤의 방영 불리","original":"Friday Night Death Slot","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"북미 방송에서 금요일 밤 편성을 낮은 시청률과 조기 종영의 위험 신호로 보는 업계 관행이다. 다른 지역의 편성 문화까지 일반화하지 않는다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-010746/index.html"},{"id":"MEJE-KW-010747","row_version":2,"title":"나중에 떠오르는 작품의 묘수","original":"Fridge Brilliance","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":null,"parent_id":null,"tag_path":["ML-F30"],"summary":"처음에는 어색했던 설정이나 사건이 감상 뒤 다른 단서를 연결하면서 설득력 있는 구성으로 새롭게 이해된다. 나중에 발견한 단서가 설정을 살리는 대신 허점을 드러낸다면 한참 뒤에 걸리는 이야기의 빈틈으로 바뀐다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"분류축","entry_url":"cards/MEJE-KW-010747/index.html"},{"id":"MEJE-KW-010748","row_version":3,"title":"뒤늦게 밀려오는 따뜻함","original":"Fridge Heartwarming","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":null,"parent_id":null,"tag_path":["ML-F30"],"summary":"감상이 끝난 뒤 인물이나 장면의 숨은 의미를 떠올리면서 처음보다 더 큰 온기와 애틋함을 느낀다. 뒤늦게 알아차린 의미가 온기보다 상실의 감정을 키우면 뒤늦게 깨닫는 슬픔에 가깝다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"분류축","entry_url":"cards/MEJE-KW-010748/index.html"},{"id":"MEJE-KW-010749","row_version":2,"title":"뒤늦게 알아차리는 섬뜩함","original":"Fridge Horror","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":null,"parent_id":null,"tag_path":["ML-F30"],"summary":"감상 당시에는 넘겼던 설정이나 사건의 함의를 나중에 생각하다가 새로운 공포를 발견한다. 같은 뒤늦은 발견이 공포보다 비극성을 드러낼 때는 뒤늦게 깨닫는 슬픔이 된다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"분류축","entry_url":"cards/MEJE-KW-010749/index.html"},{"id":"MEJE-KW-010750","row_version":1,"title":"한참 뒤에 걸리는 이야기의 빈틈","original":"Fridge Logic","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":null,"parent_id":null,"tag_path":["ML-F30"],"summary":"작품을 보는 동안 자연스럽게 넘긴 설정이나 사건이 나중에 생각하면 내부 논리와 어긋나 보인다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"분류축","entry_url":"cards/MEJE-KW-010750/index.html"},{"id":"MEJE-KW-010751","row_version":1,"title":"뒤늦게 깨닫는 슬픔","original":"Fridge Sadness","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":null,"parent_id":null,"tag_path":["ML-F30"],"summary":"이야기를 다 본 뒤 인물의 처지나 결말의 남은 함의를 곱씹으며 처음보다 더 큰 슬픔을 느낀다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"분류축","entry_url":"cards/MEJE-KW-010751/index.html"},{"id":"MEJE-KW-010752","row_version":1,"title":"친구 관계를 타고 퍼지는 소식","original":"Friending Network","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"서로 겹치는 친구 모임을 거치며 한 사람의 소식이 여러 공동체로 빠르게 번져 나간다. 연락 수단보다 인적 연결망의 구조가 확산을 만든다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-010752/index.html"},{"id":"MEJE-KW-010753","row_version":2,"title":"암시장에서 구해 주는 지인","original":"Friend in the Black Market","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"정식 경로로 얻기 어려운 물건을 신뢰 관계를 통해 구해 주는 인물이다. 도움에는 대가와 위험이 따를 수 있다. 비공식 유통망을 아는 친구와 달리 정보를 구하는 데 도움을 주는 전문 직업 인물은 기자를 아는 탐정이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-010753/index.html"},{"id":"MEJE-KW-010754","row_version":1,"title":"폭력을 택한 친구와 충돌하다","original":"Friend in the Crosshairs","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":null,"parent_id":null,"tag_path":["ML-F08"],"summary":"가까운 친구가 민간인을 겨냥한 정치적 폭력에 나서거나 이를 준비할 때 인물이 우정과 피해 방지 사이에서 선택을 강요받는다.","accent":"#936E72","tab":"#9A6A55","facet":"갈등·장애","bookmark":"분류축","entry_url":"cards/MEJE-KW-010754/index.html"},{"id":"MEJE-KW-010755","row_version":1,"title":"기자를 아는 탐정","original":"Friend in the Press","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"탐정이 신뢰하는 기자의 취재망과 자료를 통해 공식 수사만으로 얻기 어려운 정보를 찾는다. 두 직업의 협력 관계가 사건 해결을 돕는다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-010755/index.html"},{"id":"MEJE-KW-010756","row_version":2,"title":"친구가 없음을 보여 주는 배경","original":"Friendless Background","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이 혼자 밥을 먹거나 다른 무리를 멀리서 바라보는 모습을 통해 현재 곁에 가까운 친구가 없음을 말없이 보여 준다. 혼자 있는 배경을 상대가 직접 공격하는 말로 바꾸면 친구가 없다고 찌르는 말이 된다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-010756/index.html"},{"id":"MEJE-KW-010757","row_version":1,"title":"친구가 없다고 찌르는 말","original":"Friendlessness Insult","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 상대에게 아무도 그를 아끼지 않는다고 말해 관계에 대한 불안을 자극한다. 실제 친구가 있는지는 이 모욕의 성립과 별개다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-010757/index.html"},{"id":"MEJE-KW-010758","row_version":2,"title":"친근함을 보이는 이름 부르기 허락","original":"Friendly Address Privileges","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"인물이 가까운 사람에게만 이름·애칭 사용을 허락하거나, 새로 만난 상대에게 그렇게 불러 달라고 권하며 관계의 거리를 좁힌다. 적이라 해도 친밀한 호칭을 허락할 정도로 가까워졌다면 우정을 나누는 적과 이어질 수 있다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-010758/index.html"},{"id":"MEJE-KW-010759","row_version":2,"title":"우정을 나누는 적","original":"Friendly Enemy","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"서로 맞서는 인물들이 오랜 경쟁 속에서 상대를 존중하고 필요할 때 도우며 적대와 우정이 공존하는 관계를 만든다. 상대와 적대하면서도 우정을 쌓는 관계와 달리 처음부터 서로의 성장을 바라는 경쟁은 서로를 키우는 우호적 경쟁이다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-010759/index.html"},{"id":"MEJE-KW-010760","row_version":1,"title":"서로 친한 팬덤들","original":"Friendly Fandoms","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"서로 다른 작품의 팬 공동체가 관심사와 활동을 공유하며 상대 작품을 즐기거나 함께 창작한다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-010760/index.html"},{"id":"MEJE-KW-010761","row_version":1,"title":"아군 공격에는 피해를 입지 않다","original":"Friendly Fireproof","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임에서 넓은 범위의 공격이 적에게는 닿아도 같은 편의 인물에게는 피해를 주지 않는 규칙이다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-010761/index.html"},{"id":"MEJE-KW-010762","row_version":2,"title":"사람을 돕는 유령","original":"Friendly Ghost","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"무섭게 여겨지는 유령이 실제로는 사람과 이야기하고 도움을 주는 친근한 존재로 등장한다. 전통적인 공포 존재를 선량한 이웃으로 뒤집는 방식은 선량한 흡혈귀에게도 적용된다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-010762/index.html"},{"id":"MEJE-KW-010763","row_version":1,"title":"편리한 이국 배경으로 그린 차이나타운","original":"Friendly Local Chinatown","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 한 도시의 차이나타운을 이국적 음식·범죄 사건·신비로운 가게 같은 소재를 필요할 때 꺼내 쓰는 편리한 배경으로 정형화하는 재현 관습. 실제 지역과 주민의 다양성을 설명하는 개념은 아니다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-010763/index.html"},{"id":"MEJE-KW-010764","row_version":2,"title":"친근한 거미","original":"Friendly Neighborhood Spider","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"공포의 대상처럼 그려지던 거미가 사람에게 해를 주지 않고 친구나 동료가 되는 존재로 등장한다. 거미를 친근하게 묘사하듯 돌고래의 우호성도 사람과 노는 돌고래 이미지이라는 재현 관습으로 나타난다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-010764/index.html"},{"id":"MEJE-KW-010765","row_version":2,"title":"선량한 흡혈귀","original":"Friendly Neighborhood Vampire","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"위험한 괴물로 여겨지는 흡혈귀가 실제로는 타인을 아끼고 돕는 인물로 등장한다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-010765/index.html"},{"id":"MEJE-KW-010766","row_version":1,"title":"친절한 해적","original":"Friendly Pirate","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"해적의 옷차림과 말투, 모험은 지녔지만 남을 약탈하거나 해치지 않는 우호적인 인물형이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-010766/index.html"},{"id":"MEJE-KW-010767","row_version":1,"title":"사람과 노는 돌고래 이미지","original":"Friendly, Playful Dolphin","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 돌고래를 사람과 쉽게 친구가 되어 놀아 주는 동물로 그린다. 야생 개체의 실제 행동을 예측할 수 있다는 뜻은 아니다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-010767/index.html"},{"id":"MEJE-KW-010768","row_version":1,"title":"서로를 키우는 우호적 경쟁","original":"Friendly Rivalry","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"두 인물이 맞서 이기려 하면서도 상대의 실력을 존중하고 다음 대결을 통해 함께 성장한다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-010768/index.html"},{"id":"MEJE-KW-010769","row_version":2,"title":"모두가 짜고 벌인 선의의 사건","original":"Friendly Scheming","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"친구나 사랑하는 이들이 주인공을 위해 사건 전체를 선의로 꾸며 왔음이 드러나는 전개. 깜짝 행사나 시험뿐 아니라 장난·구애·심리적 도움도 동기가 될 수 있으며, 당사자가 겪은 불안은 따로 살핀다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-010769/index.html"},{"id":"MEJE-KW-010770","row_version":2,"title":"친절한 가게 주인","original":"Friendly Shopkeeper","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"손님의 필요를 잘 알고 합리적인 거래를 도우며 주인공에게 물건뿐 아니라 동네 정보와 조언도 건네는 상인 인물형이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-010770/index.html"},{"id":"MEJE-KW-010771","row_version":2,"title":"다정한 해골 캐릭터","original":"Friendly Skeleton","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"죽음의 상징인 해골을 익살스럽고 온화한 인물로 그려 두려움보다 친근함과 유쾌함을 느끼게 하는 존재형이다. 죽음을 떠올리게 하는 존재를 다정하게 바꾸는 방식은 친근한 좀비에서도 나타난다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-010771/index.html"},{"id":"MEJE-KW-010772","row_version":1,"title":"사교적인 저격수","original":"Friendly Sniper","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"전투에서는 뛰어난 저격 실력을 보이면서도 평소에는 붙임성 있고 명랑하게 동료와 어울리는 인물형이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-010772/index.html"},{"id":"MEJE-KW-010773","row_version":3,"title":"영웅 때문에 위험해진 가까운 사람","original":"Friendly Target","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"악역이 영웅의 친구나 가족을 겨냥해 감정적 타격을 주고 영웅의 행동을 흔들려는 서사 장치다. 영웅의 친구가 위험해지면 목표를 이룰지 친구를 구할지 묻는 소중한 목표와 친구 사이의 선택이 생길 수 있다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-010773/index.html"},{"id":"MEJE-KW-010774","row_version":1,"title":"장난으로 하는 간지럼","original":"Friendly Tickle Torture","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"가까운 사이의 인물들이 간지럼을 친밀한 장난이나 유혹으로 나누는 장면이다. 상대가 싫어한다면 장난이라는 의도와 별개로 멈춰야 한다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-010774/index.html"},{"id":"MEJE-KW-010775","row_version":2,"title":"적의 없는 모의 대결","original":"Friendly War","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":null,"parent_id":null,"tag_path":["ML-F08"],"summary":"서로 적처럼 맞서지만 실제로는 놀이와 공연의 일부라서 싸움이 끝나도 관계가 무너지지 않는 경쟁 구도다. 놀이로 끝날 경쟁이 선을 넘으면 경쟁으로 흔들리는 우정으로 바뀐다.","accent":"#936E72","tab":"#9A6A55","facet":"갈등·장애","bookmark":"분류축","entry_url":"cards/MEJE-KW-010775/index.html"},{"id":"MEJE-KW-010776","row_version":1,"title":"친근한 좀비","original":"Friendly Zombie","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"좀비가 이성과 감정을 지닌 채 살아 있는 사람과 우정이나 협력을 나눌 수 있는 존재로 그려지는 변형이다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-010776/index.html"},{"id":"MEJE-KW-010777","row_version":2,"title":"친구는 팔 수 없다는 선택","original":"Friend Not for Sale","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"동물이나 로봇 등 소중한 동반자를 값비싼 제안과 바꾸지 않겠다고 결정해 관계의 가치를 드러내는 장면이다. 소중한 동반자를 떠나보낼 수 없다는 선택은 우정을 상징하는 우정을 간직한 물건에 담기기도 한다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-010777/index.html"},{"id":"MEJE-KW-010778","row_version":2,"title":"내 비밀 정체와 친한 척하다","original":"Friend of Masked Self","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"이중 정체를 지닌 인물이 두 신분이 다른 사람이라는 믿음을 지키려고 자신의 비밀 정체와 친분이 있는 것처럼 말한다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-010778/index.html"},{"id":"MEJE-KW-010779","row_version":1,"title":"수사관을 돕는 경찰 친구","original":"Friend on the Force","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"사설 탐정이나 비공식 조사자를 신뢰해 필요한 정보와 공적 절차의 연결을 돕는 경찰 인물형이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-010779/index.html"},{"id":"MEJE-KW-010780","row_version":1,"title":"전장에서 아군인지 적군인지 헷갈리다","original":"Friend or Foe?","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":null,"parent_id":null,"tag_path":["ML-F08"],"summary":"혼란스러운 전투 속에서 소속을 잘못 알아보고 아군을 적으로 의심해 갈등과 위험이 생기는 상황이다.","accent":"#936E72","tab":"#9A6A55","facet":"갈등·장애","bookmark":"분류축","entry_url":"cards/MEJE-KW-010780/index.html"},{"id":"MEJE-KW-010781","row_version":2,"title":"소중한 목표와 친구 사이의 선택","original":"Friend-or-Idol Decision","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":null,"parent_id":null,"tag_path":["ML-F08"],"summary":"오랫동안 좇던 목표를 이룰 기회와 곁에 있는 친구를 구할 기회가 동시에 와서 한쪽을 포기해야 하는 선택이다. 친구를 위해 중요한 기회를 포기하는 선택은 우정이 드러나는 순간을 만드는 사건이 된다.","accent":"#936E72","tab":"#9A6A55","facet":"갈등·장애","bookmark":"분류축","entry_url":"cards/MEJE-KW-010781/index.html"},{"id":"MEJE-KW-010782","row_version":2,"title":"적처럼 굴던 두 사람이 사실 친구","original":"Friends All Along","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"서로 격하게 다투는 듯 보이던 두 인물이 갑자기 친근하게 인사하며 오래된 친구였음을 드러내는 반전이다. 서로 친구인 줄 몰랐던 반전과 이미 친구면서도 인정하지 않는 친구라는 말을 부정하다은 관계의 겉모습을 뒤집는다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-010782/index.html"},{"id":"MEJE-KW-010783","row_version":1,"title":"선택한 친구와 주어진 가족의 차이","original":"Friends Are Chosen, Family Aren't","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"인물이 친구들과는 편안하지만 가족 앞에서는 오래된 갈등으로 달라지는 모습을 통해 두 관계의 차이를 보여준다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-010783/index.html"},{"id":"MEJE-KW-010784","row_version":2,"title":"친구에서 바로 배우자로","original":"Friendship as Courtship","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"오랫동안 가까이 지낸 친구들이 서로의 마음을 깨닫고 별도의 긴 교제 단계 없이 결혼을 약속하는 관계 전개다. 오랜 친구가 함께 살면서 관계를 바꾸면 함께 살다 연인이 되다와 맞닿는다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-010784/index.html"},{"id":"MEJE-KW-010785","row_version":1,"title":"선물로 사려는 우정","original":"Friendship Bribe","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"인물이 돈과 선물, 혜택으로 사람들의 관심을 붙잡아 친구처럼 보이는 관계를 유지하려는 구도다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-010785/index.html"},{"id":"MEJE-KW-010786","row_version":2,"title":"친구라는 말을 부정하다","original":"Friendship Denial","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"서로 믿고 돕는 사이인데도 한 인물이 자존심이나 두려움 때문에 관계를 우정이라고 인정하지 않는 장면이다. 친구라는 말을 부정하던 인물이 결정적인 도움을 주면 우정이 드러나는 순간이 된다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-010786/index.html"},{"id":"MEJE-KW-010787","row_version":2,"title":"친구 사이의 편애","original":"Friendship Favoritism","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"여러 친구 중 한 사람을 더 각별히 대하는 모습이 드러나 나머지 친구가 서운해하거나 관심을 겨루는 갈등이다. 한 친구를 더 아끼는 태도가 경쟁과 결합하면 경쟁으로 흔들리는 우정이 일어날 수 있다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-010787/index.html"},{"id":"MEJE-KW-010788","row_version":3,"title":"우정을 싫어하는 적대자","original":"Friendship-Hating Antagonist","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"사람 사이의 유대를 약점이라고 여기고 친구를 믿는 주인공과 가치관으로 맞서는 적대자 인물형이다. 우정을 약점으로 보는 적대자는 주인공의 우정이 드러나는 순간을 거부한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-010788/index.html"},{"id":"MEJE-KW-010789","row_version":1,"title":"우정이 드러나는 순간","original":"Friendship Moment","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"평소에는 드러나지 않던 배려와 헌신이 한 행동에 나타나 두 인물의 우정이 확실해지는 장면이다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-010789/index.html"},{"id":"MEJE-KW-010790","row_version":1,"title":"촬영 현장에서 맺은 우정","original":"Friendship on the Set","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"한 작품을 함께 만드는 배우나 제작진이 촬영 중 서로 가까워져 작업 밖에서도 우정을 이어 가는 관계다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-010790/index.html"},{"id":"MEJE-KW-010791","row_version":1,"title":"우정 노래","original":"Friendship Song","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"두 사람 이상의 우정을 가사와 음악으로 표현하는 곡. 작품 속 인물이 직접 공연하는 장면이 없어도 성립한다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-010791/index.html"},{"id":"MEJE-KW-010792","row_version":2,"title":"경쟁으로 흔들리는 우정","original":"Friendship-Straining Competition","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"친구들이 같은 상이나 목표를 놓고 겨루다 승부에 집착하면서 원래의 관계를 해칠 위험에 놓인다. 같은 사람에게 마음을 두고 겨루면 연적이 된 친구들이 우정을 위태롭게 만든다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-010792/index.html"},{"id":"MEJE-KW-010793","row_version":1,"title":"우정을 간직한 물건","original":"Friendship Trinket","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"친구들이 나누거나 주고받은 작은 물건이 서로의 신뢰와 오래된 약속을 떠올리게 하는 상징이다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-010793/index.html"},{"id":"MEJE-KW-010794","row_version":1,"title":"형편에 비해 넓은 도심 아파트","original":"\"Friends\" Rent Control","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품 속 인물들이 드러난 직업과 수입에 비해 지나치게 넓고 좋은 도심 주거 공간에서 사는 시트콤식 재현 관습이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-010794/index.html"},{"id":"MEJE-KW-010795","row_version":2,"title":"연적이 된 친구들","original":"Friends Turned Romantic Rivals","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"친구 사이였던 두 사람 이상이 같은 인물에게 마음을 두면서 우정과 연애 사이의 갈등을 겪는다. 친구 사이의 연애 경쟁은 한 인물의 친구와 연인이 맞서는 친구와 연인이 나를 두고 다투다과 다른 갈등이다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-010795/index.html"},{"id":"MEJE-KW-010796","row_version":1,"title":"연애 약속 없이 만나는 성적 동반자","original":"Friends with Benefits","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"서로 합의해 성적 관계를 맺지만 장기 연애나 배타적인 관계는 약속하지 않는 두 인물의 관계다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-010796/index.html"},{"id":"MEJE-KW-010797","row_version":1,"title":"아이들에게 다정한 인물","original":"Friend to All Children","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"아이들을 유난히 좋아하고 다정하게 대하는 인물형. 평소 무뚝뚝하거나 어른에게 엄격한 성격과 대비되기도 하지만 그런 태도가 필수는 아니다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-010797/index.html"},{"id":"MEJE-KW-010798","row_version":2,"title":"모든 생명과 친해지는 인물","original":"Friend to All Living Things","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"동물과 자연의 생명들이 거리낌 없이 다가오는 모습을 통해 다정함이나 특별한 교감 능력을 드러내는 인물형이다. 모든 생명과 어울리는 인물 중 특히 곤충과 친한 경우는 벌레까지 아끼는 인물에 가깝다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-010798/index.html"},{"id":"MEJE-KW-010799","row_version":1,"title":"벌레까지 아끼는 인물","original":"Friend to Bugs","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"다른 사람이 꺼리는 곤충에게도 호기심과 애정을 보이며 돌보는 인물형이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-010799/index.html"},{"id":"MEJE-KW-010800","row_version":2,"title":"위험한 범죄자를 돕는 친구","original":"Friend to Psychos","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"잔혹한 범죄를 저지르는 인물 곁에 있으면서 그를 숨겨 주거나 계속 관계를 유지하는 조력자 인물형이다. 정신질환을 범죄와 연결하는 뜻은 아니다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-010800/index.html"},{"id":"MEJE-KW-010801","row_version":1,"title":"친구와 연인이 나를 두고 다투다","original":"Friend Versus Lover","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"한 인물의 시간과 애정을 놓고 오랜 친구와 연인이 서로 견제하며 관계의 우선순위를 다투는 구도다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-010801/index.html"},{"id":"MEJE-KW-010802","row_version":1,"title":"곁에 있던 친구가 사실 괴물","original":"Fright Beside Them","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"친구와 함께 있다고 믿던 인물이 진짜 친구의 등장으로 눈앞의 상대가 다른 존재였음을 깨닫는 공포 반전이다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-010802/index.html"},{"id":"MEJE-KW-010803","row_version":2,"title":"공포를 이용한 죽음의 함정","original":"Fright Deathtrap","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"악역이 피해자의 두려움을 자극해 뜻밖의 사고처럼 보이는 죽음으로 몰아가는 서사 장치다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-010803/index.html"},{"id":"MEJE-KW-010804","row_version":1,"title":"외국어를 공포의 신호로 쓰다","original":"Frightening Foreign Language","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"공포 작품이 관객에게 익숙하지 않은 언어의 소리나 글자를 불길한 분위기와 연결하는 재현 관습이다. 언어 자체가 위험하거나 기이하다는 뜻은 아니다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-010804/index.html"},{"id":"MEJE-KW-010805","row_version":1,"title":"무서워서 함께 자러 오다","original":"Fright-Induced Bunkmate","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"겁에 질린 인물이 믿는 사람에게 다가가 그날 밤 곁에서 자도 되는지 부탁해 관계의 친밀함을 보여 주는 장면. 어린 인물이 연장자에게 청하는 경우가 많다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-010805/index.html"},{"id":"MEJE-KW-010806","row_version":2,"title":"차가운 물에도 멀쩡한 인물","original":"Frigid Water Is Harmless","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"혹한의 바다나 호수에 들어간 인물이 저체온의 영향을 거의 받지 않는 것으로 그려지는 작품의 생존 관습이다. 혹한의 물에서 멀쩡한 인물과 달리 몸 밖으로 나오자마자 어는 체액은 극단적인 추위를 화면에 드러낸다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-010806/index.html"},{"id":"MEJE-KW-010807","row_version":2,"title":"화려한 프릴을 입은 정의의 전사","original":"Frills of Justice","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"마법소녀가 리본과 프릴이 많은 복장으로 싸우며 귀여움과 영웅성을 함께 드러내는 의상 양식이다. 마법소녀의 프릴 의상은 힘이 커질수록 강해질수록 화려해지는 의상으로 더 화려해질 수 있다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-010807/index.html"},{"id":"MEJE-KW-010808","row_version":1,"title":"강해질수록 화려해지는 의상","original":"Frilly Upgrade","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"마법소녀가 새 힘을 얻을 때 기존 의상에 장식과 색을 더해 성장을 눈에 띄게 보여주는 디자인 관습이다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-010808/index.html"},{"id":"MEJE-KW-010809","row_version":1,"title":"활발한 페럿 캐릭터","original":"Frisky Ferret","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 페럿을 호기심이 많고 쉬지 않고 움직이는 동물 인물로 그리는 재현 관습이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-010809/index.html"},{"id":"MEJE-KW-010810","row_version":1,"title":"무리한 소송을 제기하는 인물","original":"Frivolous Lawsuit","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 작은 불편이나 경미한 사건을 두고 과도한 소송을 제기하는 인물을 그린다. 탐욕뿐 아니라 복수심이나 과도한 정의감도 동기가 될 수 있으며, 실제 소송의 타당성을 일반화하지 않는다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-010810/index.html"},{"id":"MEJE-KW-010811","row_version":2,"title":"하찮은 일에 조력자를 부르다","original":"Frivolous Summoning","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 사소한 부탁을 위해 초자연적 존재나 평범한 조력자를 소환·호출해 주변을 어이없게 만드는 장면.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-010811/index.html"},{"id":"MEJE-KW-010812","row_version":2,"title":"개구리를 닮은 사람 종족","original":"Frog Men","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"사람과 비슷한 몸에 개구리의 얼굴과 피부, 뛰는 힘 같은 특징을 지닌 가상 종족이다. 개구리형 인물이 닌자 역할까지 맡으면 개구리와 연결된 닌자와 겹친다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-010812/index.html"},{"id":"MEJE-KW-010813","row_version":1,"title":"개구리와 연결된 닌자","original":"Frog Ninja","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"개구리로 변하거나 개구리를 동료로 삼는 능력으로 묘사되는 닌자 인물형이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-010813/index.html"},{"id":"MEJE-KW-010814","row_version":1,"title":"세포 하나에서 되살아나다","original":"From a Single Cell","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"거의 완전히 파괴된 존재가 남은 작은 세포 하나를 바탕으로 몸 전체를 다시 만드는 재생 능력이다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-010814/index.html"},{"id":"MEJE-KW-010815","row_version":1,"title":"더 나빠질 곳 없을 때 악화되다","original":"From Bad to Worse","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"이미 큰 위기에 처한 인물에게 결정적인 불행이 더해져 상황이 한 단계 더 절망적으로 바뀌는 전개다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-010815/index.html"},{"id":"MEJE-KW-010816","row_version":1,"title":"작품 밖에서 날아온 도움","original":"From Beyond the Fourth Wall","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"관객이나 창작자가 작품 안의 인물과 사건에 직접 개입해 이야기의 문제를 해결하거나 새 변수를 만드는 메타 장치다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-010816/index.html"},{"id":"MEJE-KW-010817","row_version":1,"title":"군 복무 경험을 범죄에 쓰다","original":"From Camouflage to Criminal","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 군 경력을 지닌 범죄 인물이 그때 익힌 기술을 범죄에 이용한다고 그리는 재현 관습. 군 복무가 범죄로 이어진다는 인과나 실제 집단의 속성을 뜻하지 않는다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-010817/index.html"},{"id":"MEJE-KW-010818","row_version":2,"title":"재앙이 전설이 되다","original":"From Cataclysm to Myth","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"먼 과거의 대재앙이 후대 사람들의 기억에서 흐려지고 종교나 전설 속 사건으로 다시 해석되는 세계관 설정이다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-010818/index.html"},{"id":"MEJE-KW-010819","row_version":3,"title":"형제자매처럼 자란 사촌","original":"From Cousin to Honorary Sibling","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"함께 자라거나 한집에서 지낸 사촌들이 서로를 혈연상 사촌보다 형제자매에 가까운 관계로 느낀다. 사촌을 형제자매처럼 여기는 관계는 주어진 가족과 선택한 관계를 비교하는 선택한 친구와 주어진 가족의 차이과 연결된다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-010819/index.html"},{"id":"MEJE-KW-010820","row_version":1,"title":"옷을 내어 응급 처치를 돕다","original":"From Dress to Dressing","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"도움이 필요한 사람에게 인물이 자기 옷을 희생해 당장 필요한 돌봄을 제공하며 성격과 관계를 보여주는 장면이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-010820/index.html"},{"id":"MEJE-KW-010821","row_version":2,"title":"오락 작품이 수업 자료가 되다","original":"From Entertainment to Education","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"처음에는 즐거움을 위해 만들어진 작품이 나중에 학교와 학술 공간에서 분석과 토론의 자료로 쓰이는 현상이다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-010821/index.html"},{"id":"MEJE-KW-010822","row_version":2,"title":"영웅에서 스승으로","original":"From Hero to Mentor","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"오랫동안 앞에서 싸우던 인물이 경험을 다음 세대에 전하는 스승의 역할로 옮겨 가는 인물 변화다. 평범한 사람이 영웅이 되는 성장 뒤에는 무명에서 영웅으로이라는 다음 단계가 올 수 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-010822/index.html"},{"id":"MEJE-KW-010823","row_version":1,"title":"내 정원에서 난 음식이라는 말","original":"From My Own Personal Garden","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 손님에게 대접한 음식을 자기 정원에서 길렀다고 강조해 자부심이나 기묘한 소유욕을 드러내는 대사 관습이다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-010823/index.html"},{"id":"MEJE-KW-010824","row_version":1,"title":"대도시에서 작은 마을로","original":"From New York to Nowhere","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"도시 생활에 익숙한 인물이 작은 마을로 옮겨와 낯선 관습과 이웃에 적응하면서 생활관의 차이를 겪는 전개다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-010824/index.html"},{"id":"MEJE-KW-010825","row_version":3,"title":"평범한 인물이 거대한 악역이 되다","original":"From Nobody to Nightmare","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"처음에는 눈에 띄지 않던 사람이 힘과 영향력을 얻으며 모두가 두려워하는 적대자로 바뀌는 인물 변화다. 평범한 출발점이 위협적인 악역으로 바뀌는 전개는 수치심에서 영웅이 되는 잘못의 부끄러움에서 나온 영웅심과 대조된다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-010825/index.html"},{"id":"MEJE-KW-010826","row_version":2,"title":"함께 살다 연인이 되다","original":"From Roommates to Romance","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"동거하거나 같은 방을 쓰는 두 인물이 일상을 나누며 서로를 새롭게 알아 가다가 연애 관계로 바뀐다. 함께 살던 두 사람이 이미 깊은 친구라면 친구에서 바로 배우자로로 관계가 급격히 바뀔 수 있다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-010826/index.html"},{"id":"MEJE-KW-010827","row_version":2,"title":"잘못의 부끄러움에서 나온 영웅심","original":"From Shame, Heroism","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"과거의 잘못이나 비겁함에 책임을 느낀 인물이 이를 바로잡으려 남을 돕는 영웅의 길을 택한다. 과거 잘못을 바로잡으려는 결심은 무명에서 영웅으로의 성장 동기가 될 수 있다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-010827/index.html"},{"id":"MEJE-KW-010828","row_version":2,"title":"특집 방송에서 정규 시리즈로","original":"From Special to Series","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"단발 또는 반복 특집으로 먼저 공개된 프로그램이 이후 정규 시리즈 형식으로 이어지는 제작 경로. 첫 방송 당시 정규 편성이 이미 정해져 있을 수도 있다. 특집에서 시리즈로 이어지는 경로와 전작의 끝에서 시작하는 파생작은 새 연속 작품이 생겨나는 두 방식이다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-010828/index.html"},{"id":"MEJE-KW-010829","row_version":2,"title":"길에서 만난 동물이 반려동물이 되다","original":"From Stray to Pet","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"떠돌던 동물을 만난 인물이 돌봄과 생활을 함께하며 새로운 가족 관계를 맺는 이야기다. 길에서 만난 동물을 가족처럼 받아들인 뒤에는 친구는 팔 수 없다는 선택라는 선택이 가능해진다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-010829/index.html"},{"id":"MEJE-KW-010830","row_version":1,"title":"전작의 끝에서 시작하는 파생작","original":"From the Ashes","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"한 작품의 결말을 다음 작품의 출발점으로 삼아 인물이나 세계를 이어 가는 파생 시리즈의 형식이다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-010830/index.html"},{"id":"MEJE-KW-010831","row_version":1,"title":"어원 설명으로 시작하는 발언","original":"From the Latin \"Intro Ducere\"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 어떤 말의 어원부터 들려주며 이어질 설명이나 비판에 권위와 방향을 부여하는 발화 방식이다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-010831/index.html"},{"id":"MEJE-KW-010832","row_version":1,"title":"어른보다 많이 아는 아이","original":"From the Mouths of Babes","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"어른이 예상하지 못한 지식이나 어휘를 아이가 자연스럽게 말해 놀라움이나 웃음을 만드는 인물 표현이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-010832/index.html"}]}.cards;